<template>
  <p v-if="accessDenied" role="alert">{{ $t('ACTION_NOT_ALLOWED') }}</p>
  <q-page
    v-else-if="accessGranted"
    class="supplier-comparison q-pa-md"
    data-test="touchless-supplier-compare-page"
  >
    <QBtn
      flat
      icon="arrow_back"
      :label="$t('analytics_dashboard')"
      :to="TOUCHLESS_TAB_PATH"
    />
    <h1 class="text-h5">
      {{ label('touchless_compare_suppliers', 'Compare suppliers') }}
    </h1>
    <p class="text-muted-foreground">
      {{
        $t('touchless_analysis_context', {
          period,
          type: docType || $t('touchless_all_doc_types'),
        })
      }}
    </p>
    <p v-if="loading" role="status">{{ $t('loading') }}</p>
    <p v-else-if="!keys.length">{{ $t('no_data_found') }}</p>
    <div
      v-else
      class="comparison-scroll"
      tabindex="0"
      role="region"
      :aria-label="label('touchless_compare_suppliers', 'Compare suppliers')"
    >
      <table>
        <thead>
          <tr>
            <th scope="col">{{ $t('supplier') }}</th>
            <th v-for="column in columns" :key="column.key" scope="col">
              {{ columnLabel(column) }}
              <p
                v-if="!column.row"
                :data-test="`compare-missing-${column.key}`"
              >
                {{
                  column.error
                    ? $t('failed_to_load')
                    : label('touchless_compare_not_found', 'Not found')
                }}
              </p>
              <QBtn
                v-if="column.error"
                flat
                :label="$t('retry')"
                @click="load"
              />
            </th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="measure in measures" :key="measure.field">
            <th scope="row">{{ $t(measure.label) }}</th>
            <td
              v-for="column in columns"
              :key="column.key"
              class="tabular-nums"
            >
              {{ value(column.row, measure.field) }}
            </td>
          </tr>
          <tr>
            <th scope="row">{{ $t('touchless_supplier_diagnosis') }}</th>
            <td v-for="column in columns" :key="column.key">
              <QBtn
                v-if="column.row"
                flat
                no-caps
                :label="label('touchless_compare_open', 'Open')"
                :to="{
                  name: TOUCHLESS_SUPPLIER_ROUTE,
                  params: { supplierId: column.key },
                  query: { period, ...(docType ? { doc_type: docType } : {}) },
                }"
              />
            </td>
          </tr>
        </tbody>
      </table>
    </div>
    <SupplierOutcomeChart
      v-if="!loading && keys.length"
      class="q-mt-md"
      :suppliers="outcomes"
      :period="period"
      :loading="outcomesLoading"
      :error="outcomesError"
      @retry="loadOutcomes"
    />
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { QBtn } from 'quasar';
import { touchlessService } from 'src/services';
import type {
  TouchlessBuckets,
  TouchlessSupplierOpportunity,
} from 'src/services/analytics/TouchlessService';
import SupplierOutcomeChart from './components/charts/SupplierOutcomeChart.vue';
import type { SupplierOutcomeRow } from './components/charts/SupplierOutcomeChart.vue';
import { useTouchlessIntelligenceStore } from 'src/store/touchless-intelligence.store';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import {
  TOUCHLESS_TAB_PATH,
  TOUCHLESS_SUPPLIER_ROUTE,
} from 'src/router/touchless-routes';
import {
  formatTouchlessPct,
  formatLiftPp,
  NO_VALUE,
} from 'src/utils/touchless-format';
import {
  isUnresolvedSupplier,
  supplierIdOf,
  supplierLabelWithId,
} from 'src/utils/touchless-supplier';

type Column = {
  key: string;
  row?: TouchlessSupplierOpportunity;
  error?: boolean;
};
type Measure =
  | 'pure_pct'
  | 'lost_docs'
  | 'recoverable_docs'
  | 'root_cause_domain'
  | 'expected_lift_pct';
export default defineComponent({
  components: { QBtn, SupplierOutcomeChart },
  name: 'TouchlessSupplierCompare',
  setup() {
    return {
      store: useTouchlessIntelligenceStore(),
      ...useTouchlessAccess(),
      TOUCHLESS_TAB_PATH,
      TOUCHLESS_SUPPLIER_ROUTE,
    };
  },
  data() {
    return {
      columns: [] as Column[],
      loading: false,
      requestId: 0,
      // DOCB-14450: the outcome volumes load SEPARATELY from the table above.
      // They need one diagnosis request per supplier, and a comparison that
      // renders its rates only after five of those have returned would be
      // slower for every reader to pay for a chart some of them scroll past.
      outcomes: [] as SupplierOutcomeRow[],
      outcomesLoading: false,
      outcomesError: false,
      outcomesRequestId: 0,
      measures: [
        { field: 'pure_pct', label: 'touchless_col_pure_rate' },
        { field: 'lost_docs', label: 'touchless_col_lost_docs' },
        { field: 'recoverable_docs', label: 'touchless_col_recoverable' },
        { field: 'root_cause_domain', label: 'touchless_col_root_cause' },
        { field: 'expected_lift_pct', label: 'touchless_col_expected_lift' },
      ] as { field: Measure; label: string }[],
    };
  },
  computed: {
    keys(): string[] {
      const raw = this.$route.query.suppliers;
      return [
        ...new Set(
          (typeof raw === 'string' ? raw : '')
            .split(',')
            .map((key) => key.trim())
            .filter(Boolean),
        ),
      ].slice(0, 5);
    },
    period(): string {
      const raw = this.$route.query.period;
      return typeof raw === 'string' && raw ? raw : '30d';
    },
    docType(): string | null {
      const raw = this.$route.query.doc_type;
      return typeof raw === 'string' && raw ? raw : null;
    },
  },
  watch: {
    '$route.query': {
      deep: true,
      handler() {
        this.load();
      },
    },
    accessGranted: {
      immediate: true,
      handler() {
        this.load();
      },
    },
  },
  mounted() {
    this.ensureSettingsLoaded();
  },
  beforeUnmount() {
    this.requestId++;
    this.outcomesRequestId++;
  },
  methods: {
    /**
     * The column heading. Two compared suppliers can share a name and differ
     * only by id (DOCB-14450), which would give the comparison two identical
     * headings. Falls back to the key only when the supplier failed to load,
     * because then there is nothing else to name the column with.
     */
    columnLabel(column: Column): string {
      if (!column.row) return column.key;
      if (
        isUnresolvedSupplier(column.row.supplier_key, column.row.supplier_name)
      ) {
        return this.label(
          'touchless_supplier_unidentified',
          'Supplier not identified',
        );
      }
      return supplierLabelWithId(
        column.row.supplier_name || column.key,
        supplierIdOf(column.row),
      );
    },
    label(key: string, fallback: string): string {
      const translated = this.$t(key) as string;
      return translated === key ? fallback : translated;
    },
    value(
      row: TouchlessSupplierOpportunity | undefined,
      field: Measure,
    ): string {
      if (!row) return NO_VALUE;
      if (field === 'pure_pct') return formatTouchlessPct(row[field]);
      if (field === 'expected_lift_pct') return formatLiftPp(row[field]);
      if (field === 'root_cause_domain') {
        const domain = row[field];
        return domain
          ? this.label(`touchless_domain_${domain.toLowerCase()}`, domain)
          : NO_VALUE;
      }
      return String(row[field] ?? NO_VALUE);
    },
    async load() {
      const id = ++this.requestId;
      this.columns = [];
      if (!this.accessGranted || !this.checkAccess()) return;
      this.loading = true;
      const matchingFilters =
        this.store.filters.period === this.period &&
        (this.store.filters.doc_type || null) === this.docType &&
        !this.store.filters.segment_value;
      const columns = await Promise.all(
        this.keys.map(async (key): Promise<Column> => {
          const cached = matchingFilters
            ? this.store.suppliers.find((row) => row.supplier_key === key)
            : undefined;
          if (cached) return { key, row: cached };
          try {
            const result = await touchlessService.getSupplierOpportunities({
              search: key,
              limit: 1,
              period: this.period,
              doc_type: this.docType,
            });
            return {
              key,
              row: result.data.find((row) => row.supplier_key === key),
            };
          } catch {
            return { key, error: true };
          }
        }),
      );
      if (id !== this.requestId) return;
      this.columns = columns;
      this.loading = false;
      void this.loadOutcomes();
    },

    /**
     * How many documents each compared supplier sent down each outcome.
     *
     * One diagnosis request per supplier rather than a new backend endpoint:
     * `/suppliers/opportunities`, which fills the table above, carries rates
     * and losses but no bucket counts, while `/suppliers/{key}/diagnosis`
     * already returns exactly the four terminal buckets scoped to one
     * supplier. At most five suppliers can be compared, so this is at most
     * five requests.
     *
     * A supplier whose diagnosis fails keeps its bar at zero rather than
     * removing the row: a missing bar reads as "no documents", which is a
     * different statement from "we could not ask". The widget only reports an
     * error when NONE of them answered, because that is the case where every
     * bar would be a lie.
     */
    async loadOutcomes() {
      const id = ++this.outcomesRequestId;
      const columns = this.columns.filter((column) => column.row);
      if (!columns.length) {
        this.outcomes = [];
        this.outcomesError = false;
        return;
      }
      this.outcomesLoading = true;
      this.outcomesError = false;
      const rows = await Promise.all(
        columns.map(async (column): Promise<SupplierOutcomeRow> => {
          const label = this.columnLabel(column);
          try {
            const diagnosis = await touchlessService.getSupplierDiagnosis(
              column.key,
              this.period,
              this.docType,
            );
            return {
              key: column.key,
              label,
              buckets: (diagnosis?.buckets ?? null) as TouchlessBuckets | null,
            };
          } catch {
            return { key: column.key, label, buckets: null };
          }
        }),
      );
      if (id !== this.outcomesRequestId) return;
      this.outcomes = rows;
      this.outcomesError = rows.every((row) => row.buckets === null);
      this.outcomesLoading = false;
    },
  },
});
</script>

