<template>
  <TouchlessWidgetWrapper
    :title="title"
    icon="mdi:chart-bar-stacked"
    :loading="loading"
    :error="error"
    data-test="touchless-compare-outcomes-widget"
    @retry="$emit('retry')"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        :height="chartHeight"
        :options="chartOptions"
        :series="series"
      />
      <!--
        The counts in writing as well as in the bars. A stacked bar answers
        "which supplier is worse" at a glance but not "how many documents",
        and the customer asked for the amount of documents per outcome.
      -->
      <table class="outcome-figures" data-test="touchless-compare-outcome-figures">
        <thead>
          <tr>
            <th scope="col">{{ $t('supplier') }}</th>
            <th v-for="bucket in BUCKETS" :key="bucket.key" scope="col">
              {{ $t(bucket.labelKey) }}
            </th>
            <th scope="col">
              {{ label('touchless_compare_outcomes_measured', 'Measured') }}
            </th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="row in rows" :key="row.key">
            <th scope="row">{{ row.label }}</th>
            <td
              v-for="bucket in BUCKETS"
              :key="bucket.key"
              class="tabular-nums"
              :data-test="`compare-outcome-${bucket.key}-${row.key}`"
            >
              {{ row.counts[bucket.key] }}
            </td>
            <td class="tabular-nums" :data-test="`compare-outcome-total-${row.key}`">
              {{ row.measured }}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
    <div v-else class="widget-empty" data-test="touchless-compare-outcomes-empty">
      <Icon icon="mdi:chart-bar-stacked" width="32" class="text-muted-foreground" />
      <span class="q-mt-xs text-muted-foreground text-caption">
        {{ $t('no_data_found') }}
      </span>
    </div>
  </TouchlessWidgetWrapper>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { Icon } from '@iconify/vue';
import TouchlessWidgetWrapper from '../TouchlessWidgetWrapper.vue';
import type {
  TouchlessBuckets,
  TouchlessBucketKey,
} from 'src/services/analytics/TouchlessService';

/**
 * How many documents each compared supplier sent down each outcome — DOCB-14450.
 *
 * The comparison table above states rates and losses; a reader who wants to
 * know how much work a supplier actually caused has to hold five percentages
 * in their head. This says it in documents.
 *
 * Only the FOUR terminal buckets are drawn. They are exactly the denominator
 * of the official touchless rate, so the stack length is the measured
 * population and the bars of two suppliers are comparable. Adding IN_PROGRESS
 * or NOT_ELIGIBLE would make a supplier with a large backlog look busier than
 * one with a large problem.
 */
const BUCKETS: {
  key: TouchlessBucketKey;
  labelKey: string;
  /** Quasar colour role, resolved to hex below — same roles the methodology
   *  drawer's legend uses, so the legend and the chart cannot drift apart. */
  hex: string;
}[] = [
  { key: 'PURE_TOUCHLESS', labelKey: 'touchless_kpi_pure', hex: '#21BA45' },
  { key: 'AP_TOUCHLESS', labelKey: 'touchless_kpi_ap', hex: '#009688' },
  { key: 'AP_ASSISTED', labelKey: 'touchless_kpi_ap_assisted', hex: '#F2C037' },
  {
    key: 'PROCESS_EXCEPTION',
    labelKey: 'touchless_kpi_exceptions',
    hex: '#C10015',
  },
];

export interface SupplierOutcomeRow {
  /** The supplier key, used only to key the DOM and the data-test hooks. */
  key: string;
  /** Already formatted for a reader — name plus id (DOCB-14450). */
  label: string;
  buckets: TouchlessBuckets | null;
}

export default defineComponent({
  name: 'SupplierOutcomeChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    TouchlessWidgetWrapper,
  },

  props: {
    suppliers: {
      type: Array as PropType<SupplierOutcomeRow[]>,
      default: () => [],
    },
    /** The period the counts were measured over, e.g. `30d`. */
    period: { type: String, default: '30d' },
    loading: { type: Boolean, default: false },
    error: { type: Boolean, default: false },
  },

  emits: ['retry'],

  data() {
    return { BUCKETS };
  },

  computed: {
    /**
     * The header states WHICH period produced these counts. Without it the
     * chart is a bare number that the reader cannot date, and the page's
     * period selector silently changes its meaning.
     */
    title(): string {
      return this.label(
        'touchless_compare_outcomes_title',
        `Documents measured over ${this.period}`,
      ).replace('{period}', this.period);
    },

    rows(): {
      key: string;
      label: string;
      counts: Record<TouchlessBucketKey, number>;
      measured: number;
    }[] {
      return this.suppliers.map((supplier) => {
        const counts = {} as Record<TouchlessBucketKey, number>;
        let measured = 0;
        for (const bucket of BUCKETS) {
          const count = supplier.buckets?.[bucket.key]?.count ?? 0;
          counts[bucket.key] = count;
          measured += count;
        }
        return {
          key: supplier.key,
          label: supplier.label,
          counts,
          measured,
        };
      });
    },

    /** A supplier whose every terminal bucket is zero draws nothing. */
    hasData(): boolean {
      return this.rows.some((row) => row.measured > 0);
    },

    series(): { name: string; data: number[] }[] {
      return BUCKETS.map((bucket) => ({
        name: this.$t(bucket.labelKey) as string,
        data: this.rows.map((row) => row.counts[bucket.key]),
      }));
    },

    /** Grows with the number of suppliers so the bars stay readable at five. */
    chartHeight(): number {
      return Math.max(160, 60 + this.rows.length * 52);
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: {
          toolbar: { show: false },
          background: 'transparent',
          stacked: true,
        },
        plotOptions: { bar: { horizontal: true, barHeight: '60%' } },
        dataLabels: { enabled: false },
        colors: BUCKETS.map((bucket) => bucket.hex),
        xaxis: {
          categories: this.rows.map((row) => row.label),
          labels: { style: { fontSize: '10px', colors: axisColor } },
        },
        yaxis: {
          labels: { style: { fontSize: '10px', colors: [axisColor] } },
        },
        legend: { position: 'bottom', labels: { colors: axisColor } },
        grid: { borderColor: dark ? '#374151' : '#e5e7eb' },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },

  methods: {
    /** An untranslated key renders as the key; show the English instead. */
    label(key: string, fallback: string): string {
      const translated = this.$t(key) as string;
      return translated === key ? fallback : translated;
    },
  },
});
</script>

